/* cppi::1e982d18fbbd0388b712f081460c298c6cfa77494dd7b8f9d3b8cf8ae68fe207 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-07' and end_date = '2025-04-07')
and start_date = '2025-04-07' and end_date = '2025-04-07'

/* cppi::dff0ac3d5de1a2e89ac0a6272beb9db30511a86401c3a2f3e05279d92c9adbe7 */
