/* cppi::b91c41ae2fd0a5d34822355ec7dc660b4c026964f794742b82e0f54b044efebc */
with cslxhis as(
    with cslDates as (
    select max(business_date) as business_dt, min(business_date) as previous_business_dt
    from ( select distinct(business_date) from df_trusted_prod.mds_csl_daily_history order by business_date desc limit 2 )
    ) --select * from cslDates
    select his.* from df_trusted_prod.mds_csl_daily_history his
        join cslDates cDates on (his.business_date = date(cDates.business_dt) or his.business_date = date(cDates.previous_business_dt))
        ORDER BY his.id_cppibsec
    )
    select distinct(business_date) from cslxhis

